-- ============================================================
-- ÁREA DE SEGUROS DA FROTA — Grupo Foco (Fase 1: cadastro + alerta)
-- Rodar UMA vez no SQL Editor do Supabase. Idempotente no schema.
-- O bloco de SEED (INSERT) só deve rodar UMA vez (popula a frota inicial).
-- ============================================================

create table if not exists public.seguros (
  id             bigint generated always as identity primary key,
  ordem          int,
  item           text,
  categoria      text,
  proprietario   text,
  fazenda        text,
  marca          text,
  modelo         text,
  ano            int,
  chassi         text,
  apolice        text,
  seguradora     text,
  corretor       text,
  corretor_whats text,        -- para alerta futuro (preencher)
  corretor_email text,        -- para alerta futuro (preencher)
  valor_bem      numeric,
  valor_segurado numeric,
  vigencia       date,
  sem_seguro     boolean default false,   -- itens que o grupo decidiu nao segurar
  observacoes    text,
  criado_em      timestamptz default now(),
  alterado_por   text,
  alterado_em    timestamptz
);
create index if not exists idx_seguros_vigencia on public.seguros(vigencia);

alter table public.seguros enable row level security;
drop policy if exists seg_all on public.seguros;
create policy seg_all on public.seguros for all using (true) with check (true);
grant select, insert, update, delete on public.seguros to anon, authenticated;

-- ---- SEED: frota inicial (rode só uma vez) ----
-- Se precisar recomeçar: truncate public.seguros restart identity;
